<script>
import { onMount } from 'svelte';
const KEY='me-connect-v2-data';
let users=$state([]), posts=$state([]), meId=$state(''), page=$state('home');
let mode=$state('register'), name=$state(''), username=$state(''), password=$state(''), confirm=$state(''), authError=$state('');
let draft=$state(''), commentText=$state({}), openComments=$state({}), notice=$state(''), profileId=$state('');
const me=$derived(users.find(u=>u.id===meId));
const profile=$derived(users.find(u=>u.id===profileId));
const feed=$derived([...posts].sort((a,b)=>b.createdAt-a.createdAt));
function save(){localStorage.setItem(KEY,JSON.stringify({users,posts,meId}));}
function msg(t){notice=t;setTimeout(()=>notice='',2400);}
function initials(s){return (s||'?').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function person(id){return users.find(u=>u.id===id)||{name:'Unknown member',username:'unknown',bio:''};}
function ago(t){let m=Math.max(1,Math.floor((Date.now()-t)/60000));return m<60?m+'m ago':Math.floor(m/60)+'h ago';}
onMount(()=>{try{let d=JSON.parse(localStorage.getItem(KEY)||'null');if(d){users=d.users||[];posts=d.posts||[];meId=d.meId||'';}}catch(e){} if(!users.length){users=[{id:'seed-a',name:'Amara Okafor',username:'amara.builds',bio:'Building a people-first internet.',followers:[],following:[]},{id:'seed-b',name:'David Chen',username:'davidcreates',bio:'Designer, developer and learner.',followers:[],following:[]},{id:'seed-me',name:'ME Connect',username:'meconnect',bio:'Your people. Your world.',followers:[],following:[]}];posts=[{id:'p1',userId:'seed-a',text:'The future of digital identity should put people first. One person, one identity, and more control over how we show up online. 🌍',likes:[],comments:[],createdAt:Date.now()-600000},{id:'p2',userId:'seed-b',text:'Small steps, real progress. Today I shipped a new feature, learned from the bugs, and met two amazing builders. Keep building. 🚀',likes:[],comments:[],createdAt:Date.now()-2400000},{id:'p3',userId:'seed-me',text:'A community is more than a timeline. It is the people, ideas and opportunities that grow when we connect. Welcome to ME Connect.',likes:[],comments:[],createdAt:Date.now()-5000000}];save();}});
function register(){authError='';let u=username.trim().toLowerCase().replace(/^@/,'').replace(/\s/g,'');if(!name.trim()||!u||!password){authError='Please complete all fields.';return;}if(password.length<6){authError='Use at least 6 characters for your password.';return;}if(password!==confirm){authError='Passwords do not match.';return;}if(users.some(x=>x.username===u)){authError='That username is already taken.';return;}let id=String(Date.now());users=[...users,{id,name:name.trim(),username:u,bio:'Welcome to my ME Connect profile.',followers:[],following:[],password}];meId=id;save();page='home';}
function login(){authError='';let u=username.trim().toLowerCase().replace(/^@/,'');let found=users.find(x=>x.username===u&&x.password===password);if(!found){authError='Account not found or password is incorrect on this browser.';return;}meId=found.id;save();}
function logout(){meId='';save();mode='login';password='';}
function createPost(){if(!draft.trim())return msg('Write something before posting.');posts=[{id:String(Date.now()),userId:meId,text:draft.trim(),likes:[],comments:[],createdAt:Date.now()},...posts];draft='';save();msg('Your post has been published.');}
function like(p){if(!me)return msg('Log in to like posts.');posts=posts.map(x=>x.id===p.id?{...x,likes:x.likes.includes(meId)?x.likes.filter(i=>i!==meId):[...x.likes,meId]}:x);save();}
function comment(p){let t=(commentText[p.id]||'').trim();if(!t)return msg('Write a comment first.');posts=posts.map(x=>x.id===p.id?{...x,comments:[...x.comments,{id:String(Date.now()),userId:meId,text:t,createdAt:Date.now()}]}:x);commentText[p.id]='';openComments[p.id]=true;save();}
function follow(id){if(id===meId)return;let target=users.find(x=>x.id===id),self=users.find(x=>x.id===meId);if(!target||!self)return;let yes=self.following.includes(id);users=users.map(x=>x.id===meId?{...x,following:yes?x.following.filter(v=>v!==id):[...x.following,id]}:x.id===id?{...x,followers:yes?x.followers.filter(v=>v!==meId):[...x.followers,meId]}:x);save();}
function openProfile(id){profileId=id;page='profile';}
async function share(p){let t=person(p.userId).name+' on ME Connect: '+p.text;try{if(navigator.share)await navigator.share({title:'ME Connect post',text:t});else{await navigator.clipboard.writeText(t);msg('Post copied. You can paste it to share.');}}catch(e){}}
</script>
<svelte:head><title>ME Connect — Community, connected</title></svelte:head>
{#if !me}
<div class="auth"><a class="brand" href="/"> <b>✦</b> ME<span>CONNECT</span></a><div class="auth-card"><small>YOUR COMMUNITY STARTS HERE</small><h1>{mode==='register'?'Create your account.':'Welcome back.'}</h1><p>Meet people, share ideas and build what comes next.</p>{#if mode==='register'}<label>Your name<input bind:value={name} placeholder="Your full name"></label>{/if}<label>Username<input bind:value={username} placeholder="Choose a username"></label><label>Password<input type="password" bind:value={password} placeholder="At least 6 characters"></label>{#if mode==='register'}<label>Confirm password<input type="password" bind:value={confirm} placeholder="Repeat your password"></label>{/if}{#if authError}<div class="error">{authError}</div>{/if}<button class="primary full" onclick={mode==='register'?register:login}>{mode==='register'?'Create account':'Log in'} ↗</button><div class="switch">{mode==='register'?'Already have an account?':'New to ME Connect?'} <button onclick={()=>{mode=mode==='register'?'login':'register';authError='';}}>{mode==='register'?'Log in':'Create account'}</button></div><small class="disclaimer">Prototype preview · Data is saved in this browser only.</small></div><div class="auth-art"><div>ME</div><span>YOUR PEOPLE. YOUR WORLD.</span></div></div>
{:else}
<div class="shell"><aside class="sidebar"><a class="brand" href="/" onclick={()=>page='home'}><b>✦</b> ME<span>CONNECT</span></a><small class="section-label">YOUR SPACE</small><button class:active={page==='home'} onclick={()=>page='home'}>⌂ &nbsp; Home</button><button class:active={page==='explore'} onclick={()=>page='explore'}>⌕ &nbsp; Explore</button><button onclick={()=>msg('Messages are coming soon.')}>▤ &nbsp; Messages <i>SOON</i></button><button onclick={()=>msg('Notifications are coming soon.')}>♧ &nbsp; Notifications <i>SOON</i></button><small class="section-label">META EARTH</small><button onclick={()=>msg('Meta Earth integration is coming soon.')}>◈ &nbsp; Meta Earth <i>SOON</i></button><button onclick={()=>msg('Digital identity / ME ID is coming soon.')}>◎ &nbsp; Digital identity <i>SOON</i></button><div class="side-bottom"><button class="my-profile" onclick={()=>openProfile(meId)}><b class="avatar">{initials(me.name)}</b><span>{me.name}<small>@{me.username}</small></span></button><button onclick={logout}>Log out</button></div></aside>
<main><header><div class="mobile-brand">✦ ME CONNECT</div><span>Community　/　{page}</span><button class="avatar" onclick={()=>openProfile(meId)}>{initials(me.name)}</button></header>
{#if page==='home'}
<section class="hero"><small>✦ THE COMMUNITY SPACE</small><h1>Your people.<br><em>Your world.</em></h1><p>A place to share ideas, discover people and build what comes next.</p><button class="primary" onclick={()=>document.getElementById('postbox')?.focus()}>Create a post ↗</button><div class="globe">ME</div></section>
<div class="columns"><section class="feed"><div class="feed-title"><small>WHAT'S HAPPENING</small><h2>Your feed</h2></div><div class="composer"><div class="avatar">{initials(me.name)}</div><div><textarea id="postbox" bind:value={draft} placeholder="Share something with your community..."></textarea><div class="compose-bottom"><small>Photo · Link · More <em>(coming soon)</em></small><button class="primary" onclick={createPost}>Post ↗</button></div></div></div>
{#each feed as p (p.id)}{@const author=person(p.userId)}<article class="post"><div class="post-head"><button class="avatar" onclick={()=>openProfile(author.id)}>{initials(author.name)}</button><div><button class="author" onclick={()=>openProfile(author.id)}>{author.name}</button><small>@{author.username} · {ago(p.createdAt)}</small></div><button class="dots" onclick={()=>msg('More post options are coming soon.')}>···</button></div><p>{p.text}</p><div class="counts"><span>{p.likes.length} likes</span><button onclick={()=>openComments[p.id]=!openComments[p.id]}>{p.comments.length} comments</button></div><div class="actions"><button class:liked={p.likes.includes(meId)} onclick={()=>like(p)}>{p.likes.includes(meId)?'♥':'♡'} Like</button><button onclick={()=>openComments[p.id]=!openComments[p.id]}>▢ Comment</button><button onclick={()=>share(p)}>↗ Share</button></div>{#if openComments[p.id]}<div class="comments">{#each p.comments as c}<div class="comment"><b>{person(c.userId).name}</b><span>{c.text}</span></div>{/each}{#if !p.comments.length}<small>Be the first to comment.</small>{/if}<div class="comment-input"><input bind:value={commentText[p.id]} placeholder="Write a comment..." onkeydown={e=>e.key==='Enter'&&comment(p)}><button onclick={()=>comment(p)}>Send</button></div></div>{/if}</article>{/each}
</section><aside class="right"><div class="side-card"><div class="cover"></div><div class="side-card-body"><div class="avatar large">{initials(me.name)}</div><h3>{me.name}</h3><small>@{me.username}</small><p>{me.bio}</p><div class="stats"><span><b>{me.following.length}</b>Following</span><span><b>{me.followers.length}</b>Followers</span><span><b>{posts.filter(p=>p.userId===meId).length}</b>Posts</span></div><button class="outline" onclick={()=>openProfile(meId)}>View my profile ↗</button></div></div><div class="side-card pad"><small>GOOD PEOPLE, GREAT IDEAS</small><h3>People to know</h3>{#each users.filter(u=>u.id!==meId).slice(0,4) as u}<div class="suggest"><button class="avatar" onclick={()=>openProfile(u.id)}>{initials(u.name)}</button><button class="suggest-name" onclick={()=>openProfile(u.id)}>{u.name}<small>@{u.username}</small></button><button class="follow" onclick={()=>follow(u.id)}>{me.following.includes(u.id)?'✓':'+'}</button></div>{/each}</div><div class="side-card pad"><small>ON THE HORIZON</small><h3>Coming soon</h3><p>Meta Earth · Digital identity / ME ID · Notifications · Communities</p></div></aside></div>
{:else if page==='profile' && profile}
<div class="profile-page"><div class="profile-cover"></div><div class="profile-info"><div class="avatar profile-avatar">{initials(profile.name)}</div><div class="profile-text"><h1>{profile.name}</h1><small>@{profile.username}</small><p>{profile.bio}</p><div class="stats"><span><b>{profile.followers.length}</b>Followers</span><span><b>{profile.following.length}</b>Following</span><span><b>{posts.filter(p=>p.userId===profile.id).length}</b>Posts</span></div></div>{#if profile.id!==meId}<button class="primary" onclick={()=>follow(profile.id)}>{me.following.includes(profile.id)?'Following ✓':'Follow +'}</button>{/if}</div><h2>Posts</h2>{#each feed.filter(p=>p.userId===profile.id) as p}<article class="post"><p>{p.text}</p><div class="counts"><span>{p.likes.length} likes</span><span>{p.comments.length} comments</span></div><div class="actions"><button class:liked={p.likes.includes(meId)} onclick={()=>like(p)}>{p.likes.includes(meId)?'♥':'♡'} Like</button><button onclick={()=>openComments[p.id]=!openComments[p.id]}>Comment</button><button onclick={()=>share(p)}>Share</button></div>{#if openComments[p.id]}<div class="comments">{#each p.comments as c}<div class="comment"><b>{person(c.userId).name}</b><span>{c.text}</span></div>{/each}<div class="comment-input"><input bind:value={commentText[p.id]} placeholder="Write a comment..." onkeydown={e=>e.key==='Enter'&&comment(p)}><button onclick={()=>comment(p)}>Send</button></div></div>{/if}</article>{/each}{#if !posts.some(p=>p.userId===profile.id)}<div class="empty">No posts yet.</div>{/if}</div>
{:else}
<div class="explore"><small>FIND YOUR NEXT CONNECTION</small><h1>Explore <em>your community.</em></h1><p>Discover people and ideas moving the community forward.</p><div class="people">{#each users.filter(u=>u.id!==meId) as u}<div class="person"><div class="avatar">{initials(u.name)}</div><h3>{u.name}</h3><small>@{u.username}</small><p>{u.bio}</p><button class="outline" onclick={()=>openProfile(u.id)}>View profile ↗</button></div>{/each}</div><div class="soon-panel">Meta Earth integration and Digital Identity / ME ID — <b>COMING SOON</b></div></div>
{/if}</main></div><nav class="mobile-nav"><button onclick={()=>page='home'}>⌂<small>Home</small></button><button onclick={()=>page='explore'}>⌕<small>Explore</small></button><button onclick={()=>{page='home';document.getElementById('postbox')?.focus();}}>＋<small>Create</small></button><button onclick={()=>msg('Notifications are coming soon.')}>♧<small>Alerts</small></button><button onclick={()=>openProfile(meId)}>◉<small>Profile</small></button></nav>
{/if}
{#if notice}<div class="toast">{notice}</div>{/if}
